def build_offline_exam(subject: str, topic: str = "", include_solutions: bool = False, grade: str = "9", difficulty: str = "Medium", num_mcqs: int = 60, num_short: int = 12, num_long: int = 4) -> dict:
    if subject not in SUBJECT_PROFILES:
        raise ValueError("Choose Biology, Physics, Chemistry, or Computer Science.")
    if grade not in {"9", "10"}:
        raise ValueError("Choose Class 9 or Class 10.")
    if difficulty not in {"Easy", "Medium", "Hard"}:
        raise ValueError("Choose Easy, Medium, or Hard difficulty.")
    if not isinstance(num_mcqs, int) or not 1 <= num_mcqs <= 60:
        raise ValueError("Number of MCQs must be between 1 and 60.")
    if not isinstance(num_short, int) or not 2 <= num_short <= 12 or num_short % 2:
        raise ValueError("Short-question count must be an even number from 2 to 12.")
    if not isinstance(num_long, int) or not 2 <= num_long <= 4 or num_long % 2:
        raise ValueError("Long-question count must be an even number from 2 to 4.")
    profile = GRADE_10_PROFILES[subject] if grade == "10" else SUBJECT_PROFILES[subject]
    focuses = [item.strip() for item in topic.split(",") if item.strip()] if topic else []
    seed_text = subject + "|" + difficulty + "|" + "|".join(focuses)
    rng = random.Random(sum((index + 1) * ord(char) for index, char in enumerate(seed_text)))
    mcqs = []
    for bank_index, (stem, answer, distractors) in enumerate(profile["mcqs"]):
        variations = [stem, stem + " Which option is correct?", stem.replace(" is", " should be identified as") if " is" in stem else stem, "Identify the correct term: " + stem]
        for variant_index, variant in enumerate(variations):
            number = bank_index * 4 + variant_index + 1
            options = [answer] + distractors
            rng.shuffle(options)
            labels = "A B C D".split()
            item = {"number": number, "question": variant, "options": dict(zip(labels, options)), "topic": focuses[(number - 1) % len(focuses)] if focuses else profile["topics"][(number - 1) % len(profile["topics"])]}
            if include_solutions:
                item.update(answer=labels[options.index(answer)], solution=f"The correct answer is {answer}, which matches this Grade {grade} {subject} concept.")
            mcqs.append(item)
    rng.shuffle(mcqs)
    mcqs = mcqs[:num_mcqs]
    for number, item in enumerate(mcqs, 1): item["number"] = number
    short_questions = []
    for number, prompt in enumerate(profile["short"][:num_short], 1):
        item = {"number": number, "group": (number + 1) // 2, "choice": "A" if number % 2 else "B", "question": prompt, "marks": 3, "topic": focuses[(number - 1) % len(focuses)] if focuses else profile["topics"][(number - 1) % len(profile["topics"])]}
        if include_solutions: item["solution"] = f"Give the relevant definition, supporting points and a concise example for this Grade {grade} {subject} question."
        short_questions.append(item)
    long_questions = []
    for number, prompt in enumerate(profile["long"][:num_long], 1):
        item = {"number": number, "group": (number + 1) // 2, "choice": "A" if number % 2 else "B", "question": prompt, "marks": 6, "topic": focuses[(number - 1) % len(focuses)] if focuses else profile["topics"][(number - 1) % len(profile["topics"])]}
        if include_solutions: item["solution"] = f"Write a structured answer covering definition, key features or process, relationships and one relevant example for this Grade {grade} {subject} topic."
        long_questions.append(item)
    total_marks = len(mcqs) * 0.5 + (len(short_questions) // 2) * 3 + (len(long_questions) // 2) * 6
    return {"title": f"FBISE Grade {grade} {subject} Exams ({difficulty})", "subject": subject, "grade": grade, "difficulty": difficulty, "total_marks": total_marks, "solutions_included": include_solutions, "source": "Offline syllabus bank", "mcqs": mcqs, "short_questions": short_questions, "long_questions": long_questions}
